33	     amber-800, not -700: on their own soft tint the -700s measured 4.38:1
34	     (Phase 10's audit), under 4.5:1. */
35	  --ok: #166534;
36	  --warn: #92400e;
37	  --danger: #b91c1c;
38	
39	  /* Text on a filled accent, and on the photo overlay (dark in every theme). */
40	  --on-accent: #ffffff;
41	  --on-overlay: #ffffff;
42	  /* The tile under a tenant's logo on the platform pages: white in light and
43	     dark alike, since a logo is drawn for a light background. */
44	  --logo-tile: #ffffff;
45	  --overlay: rgb(0 0 0 / 0.88);
46	  /* The photo viewer's backdrop (plan/room-cards.md): near-solid, so its bar's
47	     words never sit over the page's (0.88 let the header show through). */
48	  --viewer-bg: rgb(0 0 0 / 0.95);
49	  --overlay-control: rgb(0 0 0 / 0.55);
50	  --overlay-control-hover: rgb(0 0 0 / 0.8);
51	
52	  /* Space: a 4 px scale. */
53	  --space-1: 4px;
54	  --space-2: 8px;
55	  --space-3: 12px;
56	  --space-4: 16px;
57	  --space-5: 20px;
58	  --space-6: 24px;
59	  --space-8: 32px;
60	  --space-10: 40px;
61	
62	  /* Type: five steps. (The bar chart's SVG labels are user units, not these.) */
63	  --text-xs: 12px;
64	  --text-sm: 13px;
65	  --text-base: 15px;
66	  /* A field's text on a touch screen: iOS Safari zooms the page in when a
67	     focused input, select or textarea is under 16px, and never zooms back
68	     out. This is the one step that is not a step, used only there. */
69	  --text-touch: 16px;
70	  --text-lg: 17px;
71	  --text-xl: 22px;
72	  --leading: 1.55;
73	  --leading-tight: 1.25;
74	  --font-sans: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", sans-serif;
75	  --font-mono: ui-monospace, "Cascadia Code", "SF Mono", Consolas, monospace;
76	
77	  /* Radius. */
78	  --radius-sm: 6px;
79	  --radius-md: 8px;
80	  --radius-lg: 12px;
81	  --radius-full: 999px;
82	
83	  /* Shadow: for things that float (dialogs, drawers, popovers), not for cards. */
84	  --shadow-1: 0 1px 2px rgb(0 0 0 / 0.04), 0 1px 3px rgb(0 0 0 / 0.05);
85	  --shadow-2: 0 12px 32px rgb(0 0 0 / 0.14), 0 2px 6px rgb(0 0 0 / 0.06);
