/* tokens.css — every value the stylesheets use, in one place
   (plan/ui-refresh.md Phase 0, D-101). No other file writes a colour, a size
   or a radius as a literal; they read these.

   Three kinds of token:

   1. BASE colours. Five of them are the tenant theme's keys (lib/theme.ts,
      Postgres's tenants_theme_shape): --accent, --accent-soft, --bg, --panel,
      --ink. A tenant's theme sets them as inline custom properties on
      .tenant-root. The status colours are base too, but not themable.

   2. DERIVED colours, mixed from the base ones with color-mix(). This is how
      a tenant's accent reaches every hover and focus ring without a sixth
      theme key (Rule 2). They are declared on `:root, .tenant-root, …`, not
      on :root alone, and that matters: a custom property holding var() is
      resolved where it is DECLARED, and children inherit the result. Declared
      on :root only, --line would be mixed from :root's --ink and never see the
      tenant's colours set on .tenant-root.

   3. SCALES: space, type, radius, shadow, motion. Not colours, not themable. */

:root {
  color-scheme: light dark;

  /* Base: the theme's five keys, with their defaults. */
  --accent: #2563eb;
  --accent-soft: #eef3ff;
  --bg: #f7f7f8;
  --panel: #ffffff;
  --ink: #18181b;

  /* Base: status. Each gets its -soft and -line derived below. Green-800 and
     amber-800, not -700: on their own soft tint the -700s measured 4.38:1
     (Phase 10's audit), under 4.5:1. */
  --ok: #166534;
  --warn: #92400e;
  --danger: #b91c1c;

  /* Text on a filled accent, and on the photo overlay (dark in every theme). */
  --on-accent: #ffffff;
  --on-overlay: #ffffff;
  /* The tile under a tenant's logo on the platform pages: white in light and
     dark alike, since a logo is drawn for a light background. */
  --logo-tile: #ffffff;
  --overlay: rgb(0 0 0 / 0.88);
  /* The photo viewer's backdrop (plan/room-cards.md): near-solid, so its bar's
     words never sit over the page's (0.88 let the header show through). */
  --viewer-bg: rgb(0 0 0 / 0.95);
  --overlay-control: rgb(0 0 0 / 0.55);
  --overlay-control-hover: rgb(0 0 0 / 0.8);

  /* Space: a 4 px scale. */
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 20px;
  --space-6: 24px;
  --space-8: 32px;
  --space-10: 40px;

  /* Type: five steps. (The bar chart's SVG labels are user units, not these.) */
  --text-xs: 12px;
  --text-sm: 13px;
  --text-base: 15px;
  /* A field's text on a touch screen: iOS Safari zooms the page in when a
     focused input, select or textarea is under 16px, and never zooms back
     out. This is the one step that is not a step, used only there. */
  --text-touch: 16px;
  --text-lg: 17px;
  --text-xl: 22px;
  --leading: 1.55;
  --leading-tight: 1.25;
  --font-sans: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", sans-serif;
  --font-mono: ui-monospace, "Cascadia Code", "SF Mono", Consolas, monospace;

  /* Radius. */
  --radius-sm: 6px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-full: 999px;

  /* Shadow: for things that float (dialogs, drawers, popovers), not for cards. */
  --shadow-1: 0 1px 2px rgb(0 0 0 / 0.04), 0 1px 3px rgb(0 0 0 / 0.05);
  --shadow-2: 0 12px 32px rgb(0 0 0 / 0.14), 0 2px 6px rgb(0 0 0 / 0.06);

  /* Motion. Everything that moves also obeys prefers-reduced-motion (base.css). */
  --ease: cubic-bezier(0.2, 0.7, 0.2, 1);
  --dur-fast: 120ms;
  --dur: 200ms;

  /* Sizes of the controls. */
  --control-h: 36px;
  --control-h-sm: 30px;
}

/* Dark: the system's choice, for every page that did not pin light.
   A tenant whose theme sets a SURFACE colour (bg, panel, ink or accentSoft)
   gets data-scheme="light" on its .tenant-root (lib/theme.ts,
   pinsLightScheme): its colours were chosen for a light page, and half a
   dark palette under them would be unreadable. A theme with an accent alone
   follows the system, accent included. */
@media (prefers-color-scheme: dark) {
  :root {
    --accent: #3b82f6;
    --accent-soft: #1b2540;
    --bg: #0e0e10;
    --panel: #18181b;
    --ink: #ececef;
    --ok: #4ade80;
    --warn: #fbbf24;
    --danger: #f87171;
    --shadow-1: 0 1px 2px rgb(0 0 0 / 0.4);
    --shadow-2: 0 12px 32px rgb(0 0 0 / 0.5), 0 2px 6px rgb(0 0 0 / 0.3);
  }
}

/* A pinned-light subtree: the light defaults again, then the tenant's inline
   properties override whichever keys it set. */
[data-scheme="light"] {
  color-scheme: light;
  --accent: #2563eb;
  --accent-soft: #eef3ff;
  --bg: #f7f7f8;
  --panel: #ffffff;
  --ink: #18181b;
  --ok: #166534;
  --warn: #92400e;
  --danger: #b91c1c;
  --shadow-1: 0 1px 2px rgb(0 0 0 / 0.04), 0 1px 3px rgb(0 0 0 / 0.05);
  --shadow-2: 0 12px 32px rgb(0 0 0 / 0.14), 0 2px 6px rgb(0 0 0 / 0.06);
}

/* Derived. Declared wherever the base colours can change (see the top). */
:root, .tenant-root, [data-scheme] {
  /* 78%, measured. Phase 10's audit set 68% (at 60% muted text on villa's
     cream was 4.36:1); 2026-10-20 alteza, whose ink is #333 and whose page is
     #e1e4da, read 3.63:1 on its page and 4.36:1 on --surface-2 at 68%
     (the Payments and Unanswered tabs). 78% is 4.9:1 and 5.9:1 there. */
  --muted: color-mix(in srgb, var(--ink) 78%, var(--panel));
  /* Muted text on a grey surface (--surface-3: the segmented control). --muted
     is tuned against --panel; on --surface-3 northwind's measured 4.48:1. */
  --muted-on-surface: color-mix(in srgb, var(--ink) 78%, var(--panel));
  /* For icons, borders and placeholders only, never for text: it is under 4.5:1. */
  --faint: color-mix(in srgb, var(--ink) 40%, var(--panel));
  --line: color-mix(in srgb, var(--ink) 10%, var(--panel));
  --line-strong: color-mix(in srgb, var(--ink) 18%, var(--panel));
  --surface-2: color-mix(in srgb, var(--ink) 4%, var(--panel));
  --surface-3: color-mix(in srgb, var(--ink) 8%, var(--panel));
  --field: var(--panel);
  /* Mixing toward --ink darkens on a light page and lightens on a dark one:
     the right hover in both. */
  --accent-hover: color-mix(in srgb, var(--accent) 85%, var(--ink));
  /* The accent used as TEXT: nudged toward --ink for contrast on --panel. */
  --accent-text: color-mix(in srgb, var(--accent) 85%, var(--ink));
  --ring: color-mix(in srgb, var(--accent) 35%, transparent);
  --ok-soft: color-mix(in srgb, var(--ok) 10%, var(--panel));
  --ok-line: color-mix(in srgb, var(--ok) 30%, var(--panel));
  --warn-soft: color-mix(in srgb, var(--warn) 10%, var(--panel));
  --warn-line: color-mix(in srgb, var(--warn) 30%, var(--panel));
  --danger-soft: color-mix(in srgb, var(--danger) 9%, var(--panel));
  --danger-line: color-mix(in srgb, var(--danger) 30%, var(--panel));
  /* The staff calendar's date backgrounds (plan/calendar.md § 4.1, D-103):
     a step stronger than the badges' 10%, so a whole cell reads at a glance;
     text on them stays --ink. Closed is the grey surface plus a hatch. */
  --cal-available: color-mix(in srgb, var(--ok) 13%, var(--panel));
  --cal-partial: color-mix(in srgb, var(--warn) 18%, var(--panel));
  --cal-full: color-mix(in srgb, var(--danger) 17%, var(--panel));
  --cal-closed: var(--surface-3);
  --cal-hatch: color-mix(in srgb, var(--ink) 14%, transparent);
  /* A FILL under --on-accent (white): a primary button, the visitor's bubble,
     a solid danger button. On a light page, the colour itself. */
  --accent-fill: var(--accent);
  --accent-fill-hover: var(--accent-hover);
  --danger-fill: var(--danger);
  /* The public pages' brand band and welcome cover (plan/public-brand.md):
     with no banner, a gradient from the accent to a deep shade of it; over
     a banner, a scrim of that deep shade, darkest where the text sits.
     White (--on-overlay) is the text on both: the deep end is 45% black,
     dark enough under any accent a tenant picks. */
  --hero-deep: color-mix(in srgb, var(--accent) 55%, black);
  --hero-scrim: color-mix(in srgb, var(--hero-deep) 78%, transparent);
  --hero-scrim-light: color-mix(in srgb, var(--hero-deep) 18%, transparent);
}

/* On a dark page the accent is light, and white on it measured 3.68:1
   (#3b82f6; #f87171 too; Phase 10's audit). The fill is darkened toward
   black instead: 72% gives white >= 4.98:1 on the default blue, the dark
   danger and villa's teal, and a tenant's accent keeps its hue. Hover goes
   darker still, the way it reads on a light page. Not under a pinned-light
   subtree, which keeps the light rule above. */
@media (prefers-color-scheme: dark) {
  :root, .tenant-root:not([data-scheme]) {
    --accent-fill: color-mix(in srgb, var(--accent) 72%, black);
    --accent-fill-hover: color-mix(in srgb, var(--accent) 62%, black);
    --danger-fill: color-mix(in srgb, var(--danger) 72%, black);
  }
}

