apps\web\app\styles\screens.css:309:.book-main { max-width: 1040px; }
apps\web\app\styles\screens.css:372:.book-summary { position: sticky; top: calc(var(--space-6) + 56px); margin-bottom: 0; }
apps\web\app\styles\screens.css:373:.book-summary h2 { font-size: var(--text-base); }
apps\web\app\styles\screens.css:382:.book-summary .quote { background: none; padding: 0; margin-bottom: var(--space-4); }
apps\web\app\styles\screens.css:383:.book-summary .quote.error { background: var(--danger-soft); padding: 10px var(--space-3); }
apps\web\app\styles\screens.css:384:.book-summary .quote-total { font-size: var(--text-lg); padding-top: var(--space-2); margin-top: var(--space-2); }
apps\web\app\styles\screens.css:865:.manage-summary .manage-another { width: 100%; justify-content: center; margin-top: var(--space-4); }
apps\web\app\styles\screens.css:1420:.feature-list { list-style: none; margin: 0; padding: 0; }
apps\web\app\styles\screens.css:1421:.feature-row { display: flex; align-items: center; gap: var(--space-4); padding: var(--space-3) 0; }
apps\web\app\styles\screens.css:1422:.feature-row + .feature-row { border-top: 1px solid var(--line); }
apps\web\app\styles\screens.css:1423:.feature-text { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
apps\web\app\styles\screens.css:1424:.feature-name { font-weight: 600; }
apps\web\app\styles\screens.css:1429:.switch-track { position: relative; width: 36px; height: 20px; border-radius: var(--radius-full); background: var(--surface-3); box-shadow: inset 0 0 0 1px var(--line-strong); transition: background 120ms; }
apps\web\app\styles\screens.css:1430:.switch-thumb { position: absolute; top: 2px; left: 2px; width: 16px; height: 16px; border-radius: var(--radius-full); background: var(--panel); box-shadow: var(--shadow-1); transition: transform 120ms; }
apps\web\app\styles\screens.css:1433:.switch-word { min-width: 2.2em; font-size: var(--text-sm); font-weight: 500; text-align: left; }
apps\web\app\styles\screens.css:1534:.legal-main { max-width: 760px; margin: 0 auto; padding: var(--space-6) var(--space-4) var(--space-8); }
apps\web\app\styles\screens.css:1535:.legal-doc h1 { margin-bottom: var(--space-1); }
apps\web\app\styles\screens.css:1536:.legal-version { margin: 0 0 var(--space-4); }
apps\web\app\styles\screens.css:1537:.legal-draft { margin-bottom: var(--space-6); }
apps\web\app\styles\screens.css:1538:.legal-doc h2 { margin: var(--space-6) 0 var(--space-2); font-size: var(--text-lg); }
