/* --- composer ----------------------------------------------------------- */

/* One rounded field on the page, the send arrow inside it (Phase 3). The
   focus ring goes round the whole field, not the textarea alone. */
.composer { position: relative; padding: var(--space-2) var(--space-5) var(--space-3); background: linear-gradient(to bottom, transparent, var(--bg) 30%); }
.composer-inner {
  max-width: 760px;
  margin: 0 auto;
  display: flex;
  align-items: flex-end;
  gap: var(--space-2);
  padding: 6px 6px 6px var(--space-4);
  border: 1px solid var(--line-strong);
  border-radius: 24px;
  background: var(--field);
  box-shadow: var(--shadow-1);
  transition: border-color var(--dur-fast) var(--ease), box-shadow var(--dur-fast) var(--ease);
}
.composer-inner:focus-within { border-color: var(--accent); box-shadow: 0 0 0 3px var(--ring); }
.composer textarea {
  flex: 1;
  min-height: 36px;
  /* Six lines, then it scrolls. */
  max-height: calc(6 * 1.55em + 16px);
  padding: 7px 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  resize: none;
}
.composer textarea:focus { box-shadow: none; }
.composer-send { flex: none; width: 36px; min-height: 36px; padding: 0; border-radius: var(--radius-full); }
/* Voice (plan/voice.md, D-134): the microphone beside Send; red while it records. */
.composer-mic { flex: none; width: 36px; min-height: 36px; padding: 0; border-radius: var(--radius-full); border-color: transparent; background: transparent; box-shadow: none; color: var(--muted); }
.composer-mic:hover:not(:disabled) { background: var(--surface-2); color: var(--ink); }
.composer-mic.listening { background: var(--danger-fill); color: var(--on-accent); animation: mic-pulse 1.4s var(--ease) infinite; }
.composer-mic.listening:hover:not(:disabled) { background: var(--danger-fill); color: var(--on-accent); }
@keyframes mic-pulse { 0%, 100% { box-shadow: 0 0 0 0 var(--ring); } 50% { box-shadow: 0 0 0 6px var(--ring); } }
@media (prefers-reduced-motion: reduce) { .composer-mic.listening { animation: none; } }
/* What voice is doing, in words, above the field; empty, it takes no room. */
.voice-status { max-width: 760px; margin: 0 auto var(--space-2); padding: 0 var(--space-4); display: flex; align-items: center; gap: var(--space-3); font-size: var(--text-sm); color: var(--muted); }
.voice-status:empty { display: none; }
.voice-status.error { color: var(--danger); }
.read-aloud { display: inline-flex; align-items: center; gap: var(--space-1); font-size: var(--text-xs); color: var(--muted); }
.read-aloud[aria-pressed="true"] { color: var(--ink); }
/* The fine print under the field, inset to the field's text so both edges
   line up with what is typed. ONE grid: the notice on the left, and on the
   right the keys, the Read aloud toggle and the links to the other pages,
   so the foot is as tall as the notice and no taller. */
.composer-foot {
  max-width: 760px;
  margin: var(--space-2) auto 0;
  padding: 0 var(--space-4);
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-areas: "notice side" "notice links";
  column-gap: var(--space-6);
  row-gap: var(--space-1);
  align-items: start;
  font-size: var(--text-xs);
  line-height: 1.5;
  color: var(--muted);
}
/* D-129: the chat's notice of what happens to a message. */
.composer-notice { grid-area: notice; min-width: 0; margin: 0; text-wrap: pretty; }
/* D-136, D-129: the other guest pages, Privacy and Terms, as one row that
   wraps. The dots between them are drawn here, not typed, so a wrapped row
   never starts with one. */
.composer-links { grid-area: links; display: flex; flex-wrap: wrap; justify-content: flex-end; align-items: baseline; gap: 2px 0; min-width: 0; }
.composer-links a { color: inherit; text-underline-offset: 2px; }
.composer-links a:hover { color: var(--ink); }
.composer-links a + a::before { content: "·"; margin: 0 6px; color: var(--faint); text-decoration: none; display: inline-block; }
.composer-side { grid-area: side; display: flex; flex-direction: column; align-items: flex-end; gap: var(--space-1); }
.composer-hint { margin: 0; white-space: nowrap; }
.composer-hint kbd {
