559	              el.style.height = `${el.scrollHeight}px`;
560	            }}
561	            onKeyDown={(event) => {
562	              // Enter sends; Shift+Enter inserts a newline.
563	              if (event.key === 'Enter' && !event.shiftKey) {
564	                event.preventDefault();
